from solution import fibfib
import pytest
from hypothesis import given, example
import hypothesis.strategies as st


def _ref(n: int) -> int:
    # Obviously-correct iterative reference model
    if n == 0:
        return 0
    if n == 1:
        return 0
    if n == 2:
        return 1
    a, b, c = 0, 0, 1
    for _ in range(3, n + 1):
        a, b, c = b, c, a + b + c
    return c


def test_base_zero():
    assert fibfib(0) == 0


def test_base_one():
    assert fibfib(1) == 0


def test_base_two():
    assert fibfib(2) == 1


def test_spec_example_1():
    assert fibfib(1) == 0


def test_spec_example_5():
    assert fibfib(5) == 4


def test_spec_example_8():
    assert fibfib(8) == 24


def test_spec_first_nine_values():
    expected = [0, 0, 1, 1, 2, 4, 7, 13, 24]
    for n, v in enumerate(expected):
        assert fibfib(n) == v


def test_return_type_is_int():
    for n in [0, 1, 2, 5, 8]:
        assert isinstance(fibfib(n), int)


@given(st.integers(min_value=0, max_value=15))
def test_equivalence_to_iterative_reference(n):
    assert fibfib(n) == _ref(n)


@given(st.integers(min_value=3, max_value=15))
def test_recurrence_relation(n):
    assert fibfib(n) == fibfib(n - 1) + fibfib(n - 2) + fibfib(n - 3)


@given(st.integers(min_value=0, max_value=14))
def test_successor_recurrence(n):
    # metamorphic: next value determined by previous three
    assert fibfib(n + 3) == fibfib(n + 2) + fibfib(n + 1) + fibfib(n)


@given(st.integers(min_value=2, max_value=15))
def test_non_decreasing_from_two(n):
    assert fibfib(n + 1) >= fibfib(n)


def test_non_negative():
    for n in range(0, 16):
        assert fibfib(n) >= 0


def test_efficient_completes_for_moderate_n():
    # Spec requires efficient computation. Naive exponential
    # recursion cannot compute this promptly.
    assert fibfib(25) == 755476


def test_efficient_sequential_values():
    assert fibfib(20) == 35890
    assert fibfib(24) == 410744
    assert fibfib(25) == 755476
